targets.query:
// Age in seconds. Shared by both streams so the two cannot drift apart.
age = (t) => float(v: int(v: now()) - int(v: t)) / 1000000000.0

air = from(bucket: "sensors")
  |> range(start: -7d)
  |> filter(fn: (r) => r._measurement == "air" and r.device != "sim")
  |> group(columns: ["device", "_field"])
  |> last()
  |> map(fn: (r) => ({ device: r.device, _field: r._field, _value: age(t: r._time) }))

// The AS7341 publishes to its own measurement, so a query that stopped at `air`
// could never show it. That is not hypothetical: on 2026-08-14 and again on
// 08-16 the spectrum feed went silent for 32 minutes while every cell in this
// table stayed green. A dropped sensor showing as green is the one outcome this
// panel exists to prevent.
//
// `mode` is load-bearing. A reflectance run writes to the SAME measurement as
// mode "reflect" and holds the sensor while it goes, so counting those samples
// would let an active bench session hide a dead ambient feed.
//
// One column rather than ten: the channels are a single JSON publish, they
// arrive together or not at all, so `clear` stands in for all of them.
spectrum = from(bucket: "sensors")
  |> range(start: -7d)
  |> filter(fn: (r) => r._measurement == "spectrum" and r.mode == "ambient"
       and r._field == "clear" and r.device != "sim")
  |> group(columns: ["device"])
  |> last()
  |> map(fn: (r) => ({ device: r.device, _field: "as7341", _value: age(t: r._time) }))

union(tables: [air, spectrum])
  |> group()
  |> keep(columns: ["device", "_field", "_value"])
  |> pivot(rowKey: ["device"], columnKey: ["_field"], valueColumn: "_value")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "photone" and (r._field == "ppfd" or r._field == "lamp_state") and r.device == "livingroom")
  |> pivot(rowKey: ["_time", "source"], columnKey: ["_field"], valueColumn: "_value")
  // a daylight row under a lit lamp is the ref-anchor recording — measured at the
  // lux_ref spot (sky-only field), it doesn't belong on this plant-position overlay
  |> filter(fn: (r) => not (r.source == "daylight" and exists r.lamp_state and r.lamp_state == 1.0))
  |> map(fn: (r) => ({ _time: r._time, _value: r.ppfd, source: r.source }))
  |> group(columns: ["source"])
  |> yield(name: "Photone")

from(bucket: "sensors")
  |> range(start: -30d)
  |> filter(fn: (r) => r._measurement == "photone" and (r._field == "ppfd" or r._field == "spec_ppfd_at" or r._field == "lux_at" or r._field == "n" or r._field == "paired" or r._field == "lamp_state"))
  |> pivot(rowKey: ["_time", "source"], columnKey: ["_field"], valueColumn: "_value")
  // -1 is the per-stream "refused" sentinel; a ratio against it is meaningless.
  // daylight rows with lamp_state=1 are ref-anchor rows: spec/lux are -1 BY DESIGN.
  |> map(fn: (r) => ({ _time: r._time, source: r.source, photone: r.ppfd, spectrum: r.spec_ppfd_at, lux_div54: if r.lux_at > 0.0 then r.lux_at / 54.0 else -1.0, k_spec: if r.spec_ppfd_at > 0.0 then r.ppfd / r.spec_ppfd_at else -1.0, k_lux: if r.lux_at > 0.0 then r.ppfd / (r.lux_at / 54.0) else -1.0, n: r.n, paired: r.paired, lamp_state: if exists r.lamp_state then r.lamp_state else -1.0 }))
  |> group()
  |> sort(columns: ["_time"], desc: true)
  |> keep(columns: ["_time", "source", "photone", "spectrum", "lux_div54", "k_spec", "k_lux", "n", "paired", "lamp_state"])

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "air" and r._field == "rssi" and r.device == "livingroom")
  // min, not mean: for a link-quality diagnostic the WORST value in the window is
  // the event. A 30-second drop to -85 averaged against a good hour disappears.
  |> aggregateWindow(every: v.windowPeriod, fn: min, createEmpty: false)
  |> keep(columns: ["_time", "_value"])
  |> yield(name: "RSSI (dBm, worst in window)")

from(bucket: "sensors")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "air" and r._field == "rssi" and r.device == "livingroom")
  // The gap between rssi samples IS the gap between telemetry publishes, because
  // the firmware only adds this field when WiFi is connected — so it is present on
  // every successful publish, by construction. Using temp instead would be
  // fragile: the BME680 vanished from the payload for 20 hours on 2026-08-15
  // while the board kept publishing perfectly well.
  |> elapsed(unit: 1s)
  |> map(fn: (r) => ({_time: r._time, _value: float(v: r.elapsed)}))
  |> aggregateWindow(every: v.windowPeriod, fn: max, createEmpty: false)
  |> keep(columns: ["_time", "_value"])
  |> yield(name: "發送間隔 (s, 最長)")
